<template>
  <div class="space-y-6">
    <div class="payment-tabs" role="tablist">
      <button v-for="tab in tabs" :key="tab.id" type="button" role="tab" :aria-selected="activeTab === tab.id" class="payment-tab" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">
        <component :is="tab.icon" :size="15" stroke-width="1.8" />
        <span>{{ tab.label }}</span>
      </button>
    </div>
    <div v-if="loading" class="flex justify-center py-20"><AppSpinner /></div>
    <div v-else-if="errorMessage" class="rounded-lg border border-error-30 bg-error-10 p-4 text-sm text-error">{{ errorMessage }}</div>

    <section v-else-if="activeTab === 'dashboard'" class="space-y-5">
      <div class="grid gap-4 sm:grid-cols-3"><div class="metric"><span>{{ locale.admin.orders }}</span><b>{{ dashboard.orderCount || 0 }}</b></div><div class="metric"><span>{{ locale.amount }}</span><b>{{ money(dashboard.revenueCents || 0) }}</b></div><div class="metric"><span>{{ locale.refunded }}</span><b>{{ money(dashboard.refundCents || 0) }}</b></div></div>
      <div class="rounded-lg border border-border-secondary bg-bg-secondary p-5"><h3 class="mb-4 font-black">{{ locale.method }}</h3><div v-for="item in dashboard.byMethod || []" :key="item.method" class="flex justify-between border-b border-border-secondary py-3 last:border-0"><span>{{ methodLabel(item.method) }}</span><b>{{ money(Number(item.revenueCents || 0)) }} / {{ item.orders }}</b></div></div>
    </section>

    <form v-else-if="activeTab === 'settings'" class="payment-settings" @submit.prevent="saveSettings">
      <header class="settings-header">
        <div><h2>支付设置</h2><p>配置支付系统选项与用户端展示内容</p></div>
        <a href="#payment-help" class="guide-link">↗ 支付配置指南</a>
      </header>
      <section class="settings-section settings-enable">
        <div><h3>启用支付</h3><p>启用或禁用支付系统</p></div>
        <button type="button" class="switch" :class="{ active: settings.enabled }" :aria-pressed="settings.enabled" @click="settings.enabled = !settings.enabled"><span /></button>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>商品信息</h3><span>支付页面中显示的商品名称</span></div>
        <div class="settings-grid product-grid"><Field v-model="settings.productNamePrefix" label="商品名前缀" placeholder="VoiceHub 点歌券" /><Field v-model="settings.productNameSuffix" label="商品名后缀" placeholder="例如：套餐" /><div class="field"><span>预览</span><div class="input preview">{{ settings.productNamePrefix || 'VoiceHub 点歌券' }}100 {{ settings.currency || 'CNY' }}{{ settings.productNameSuffix }}</div></div></div>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>金额与订单</h3><span>金额单位均为分，留空表示不限制</span></div>
        <div class="settings-grid amount-grid"><Field v-model.number="settings.minAmountCents" type="number" label="最低金额" /><Field v-model.number="settings.maxAmountCents" type="number" label="最高金额" placeholder="不限制" /><Field v-model.number="settings.dailyLimitCents" type="number" label="每日限额" placeholder="不限制" /><Field v-model.number="settings.orderTimeoutMinutes" type="number" label="订单超时时间" /><Field v-model.number="settings.maxPendingOrders" type="number" label="最大待支付订单数" /><Field v-model.number="settings.balanceRechargeMultiplier" type="number" step="0.01" label="点歌券价值倍率" /><Field v-model.number="settings.subscriptionUsdToCnyRate" type="number" step="0.01" label="套餐 USD/CNY 汇率" placeholder="未启用" /><Field v-model.number="settings.rechargeFeeRate" type="number" step="0.01" label="支付手续费率" /></div>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>支付策略</h3><span>控制通道选择与订单行为</span></div>
        <div class="settings-grid strategy-grid"><div class="field"><span>负载均衡策略</span><CustomSelect v-model="settings.loadBalanceStrategy" :options="balanceOptions" /></div><div class="field"><span>限制取消频率</span><div class="inline-controls"><button type="button" class="switch small" :class="{ active: settings.cancelLimitEnabled }" :aria-pressed="settings.cancelLimitEnabled" @click="settings.cancelLimitEnabled = !settings.cancelLimitEnabled"><span /></button><CustomSelect v-model="settings.cancelWindowMode" :options="cancelModeOptions" :disabled="!settings.cancelLimitEnabled" class="compact-select" /><span class="muted">每</span><input v-model.number="settings.cancelWindowMinutes" class="input compact" type="number" min="1" :disabled="!settings.cancelLimitEnabled"><CustomSelect v-model="settings.cancelWindowUnit" :options="cancelUnitOptions" :disabled="!settings.cancelLimitEnabled" class="compact-select" /><span class="muted">最多</span><input v-model.number="settings.cancelMaxCount" class="input compact" type="number" min="1" :disabled="!settings.cancelLimitEnabled"><span class="muted">次</span></div></div></div>
        <label class="setting-toggle"><button type="button" class="switch small" :class="{ active: settings.alipayForceQrCode }" :aria-pressed="settings.alipayForceQrCode" @click="settings.alipayForceQrCode = !settings.alipayForceQrCode"><span /></button><span><b>支付宝强制二维码支付</b><small>移动端支付宝统一使用二维码，不跳转手机网站</small></span></label><label class="setting-toggle"><button type="button" class="switch small" :class="{ active: settings.alipayMobileDeepLink }" :aria-pressed="settings.alipayMobileDeepLink" @click="settings.alipayMobileDeepLink = !settings.alipayMobileDeepLink"><span /></button><span><b>支付宝移动端当面付唤起</b><small>移动端优先尝试打开支付宝客户端，失败时回退二维码</small></span></label>
      </section>
      <section class="settings-section">
        <div class="section-heading"><h3>启用的支付方式</h3><span>用户将在支付页看到已启用的方式</span></div>
        <div class="method-list"><label v-for="method in methods" :key="method" class="method-chip" :class="{ selected: settings.visibleMethods?.includes(method) }"><input v-model="settings.visibleMethods" type="checkbox" :value="method"><span>{{ methodLabel(method) }}</span></label></div>
      </section>
      <section id="payment-help" class="settings-section help-section"><div class="section-heading"><h3>帮助内容</h3><span>为用户提供支付说明</span></div><div class="help-grid"><div class="help-image"><span>帮助图片链接</span><input v-model="settings.helpImageUrl" class="input" placeholder="上传或输入图片链接"><div v-if="settings.helpImageUrl" class="help-preview"><img :src="settings.helpImageUrl" alt="帮助图片预览"></div></div><textarea v-model="settings.helpText" rows="5" class="input help-input" placeholder="输入帮助说明文本..." /></div></section>
      <section class="settings-section provider-inline"><div class="section-heading provider-heading"><div><h3>服务商管理</h3><span>配置支付通道及其密钥，启用后可在支付策略中使用</span></div><button type="button" class="small-button" @click="editProvider()"><Plus :size="14" />添加服务商</button></div><div v-if="providers.length" class="provider-list"><article v-for="provider in providers" :key="provider.id" class="provider-row"><div><b>{{ provider.name }}</b><span>{{ provider.providerKey }} · {{ provider.supportedMethods.map(methodLabel).join(' / ') }}</span></div><button type="button" class="small-button" @click="editProvider(provider)"><Pencil :size="14" />编辑</button></article></div><div v-else class="empty-provider">暂未配置支付服务商</div></section>
      <footer class="settings-footer"><span>修改后保存即可立即生效</span><button class="primary-button" :disabled="saving"><Save :size="16" />{{ locale.admin.save }}</button></footer>
    </form>

    <section v-else-if="activeTab === 'providers'" class="space-y-4">
      <div class="flex justify-end"><button class="primary-button" @click="editProvider()"><Plus :size="16" />{{ locale.admin.add }}</button></div>
      <div class="grid gap-4 lg:grid-cols-2"><article v-for="provider in providers" :key="provider.id" class="rounded-lg border border-border-secondary bg-bg-secondary p-5"><div class="flex items-start justify-between gap-3"><div><h3 class="font-black">{{ provider.name }}</h3><p class="text-xs uppercase text-text-tertiary">{{ provider.providerKey }}</p></div><span :class="provider.enabled ? 'text-success' : 'text-text-disabled'">{{ provider.enabled ? 'ON' : 'OFF' }}</span></div><p class="mt-3 text-sm text-text-tertiary">{{ provider.supportedMethods.map(methodLabel).join(' / ') }}</p><div class="mt-4 flex gap-2"><button class="small-button" @click="editProvider(provider)"><Pencil :size="14" />编辑</button><button class="small-button text-error" @click="removeProvider(provider)"><Trash2 :size="14" />删除</button></div></article></div>
    </section>

    <section v-else-if="activeTab === 'plans'" class="space-y-4">
      <div class="flex justify-end"><button class="primary-button" @click="editPlan()"><Plus :size="16" />{{ locale.admin.add }}</button></div>
      <div class="overflow-x-auto rounded-lg border border-border-secondary"><table class="w-full text-left text-sm"><thead class="bg-bg-secondary text-text-tertiary"><tr><th class="p-3">名称</th><th class="p-3">价格</th><th class="p-3">点歌券</th><th class="p-3">状态</th><th class="p-3"></th></tr></thead><tbody><tr v-for="plan in plans" :key="plan.id" class="border-t border-border-secondary"><td class="p-3 font-bold">{{ plan.name }}</td><td class="p-3">{{ money(plan.priceCents, plan.currency) }}</td><td class="p-3">{{ plan.cardCount }}</td><td class="p-3">{{ plan.forSale ? '在售' : '下架' }}</td><td class="p-3"><div class="flex gap-2"><button class="small-button" @click="editPlan(plan)"><Pencil :size="14" /></button><button class="small-button text-error" @click="removePlan(plan)"><Trash2 :size="14" /></button></div></td></tr></tbody></table></div>
    </section>

    <section v-else class="space-y-4">
      <div class="flex flex-wrap gap-3"><input v-model="orderFilters.keyword" class="input max-w-xs" placeholder="订单号 / 用户" @keyup.enter="loadOrders" /><CustomSelect v-model="orderFilters.status" :options="statusOptions" class="w-44" /><button class="small-button" @click="loadOrders"><Search :size="15" />查询</button></div>
      <div class="overflow-x-auto rounded-lg border border-border-secondary"><table class="w-full text-left text-sm"><thead class="bg-bg-secondary text-text-tertiary"><tr><th class="p-3">订单</th><th class="p-3">用户</th><th class="p-3">金额</th><th class="p-3">渠道</th><th class="p-3">状态</th><th class="p-3">操作</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id" class="border-t border-border-secondary"><td class="p-3"><b>{{ order.planName }}</b><code class="block text-xs text-text-disabled">{{ order.outTradeNo }}</code></td><td class="p-3">{{ order.userName }}</td><td class="p-3">{{ money(order.payAmountCents, order.currency) }}</td><td class="p-3">{{ methodLabel(order.paymentMethod) }}</td><td class="p-3">{{ order.status }}</td><td class="p-3"><div class="flex gap-2"><button v-if="['PENDING','PAID','FAILED','EXPIRED'].includes(order.status)" class="small-button" @click="verifyOrder(order)"><RefreshCw :size="14" /></button><button v-if="['COMPLETED','REFUND_REQUESTED'].includes(order.status)" class="small-button" @click="openRefund(order)"><Undo2 :size="14" /></button></div></td></tr></tbody></table></div>
    </section>

    <Teleport to="body">
      <div v-if="providerDraft" class="modal" @click.self="providerDraft = null"><form class="dialog max-w-2xl" @submit.prevent="saveProvider"><h2>支付服务商</h2><div class="grid gap-4 sm:grid-cols-2"><div><label>类型</label><CustomSelect v-model="providerDraft.providerKey" :options="providerOptions" :disabled="!!providerDraft.id" /></div><Field v-model="providerDraft.name" label="名称" /><Field v-model.number="providerDraft.sortOrder" type="number" label="排序" /></div><label class="check"><input v-model="providerDraft.enabled" type="checkbox" />启用</label><label class="check"><input v-model="providerDraft.refundEnabled" type="checkbox" />允许退款</label><label class="check"><input v-model="providerDraft.allowUserRefund" type="checkbox" />允许用户申请退款</label><div><label>{{ locale.admin.supportedMethods }}</label><div class="flex gap-4"><label v-for="method in providerMethods" :key="method" class="check"><input v-model="providerDraft.supportedMethods" type="checkbox" :value="method" />{{ methodLabel(method) }}</label></div></div><div><label>{{ locale.admin.config }}</label><textarea v-model="providerConfigJson" rows="9" class="input w-full font-mono text-xs" /></div><div><label>实例限额 JSON</label><textarea v-model="providerLimitsJson" rows="3" class="input w-full font-mono text-xs" /></div><div class="dialog-actions"><button type="button" class="small-button" @click="providerDraft = null">取消</button><button class="primary-button">保存</button></div></form></div>
      <div v-if="planDraft" class="modal" @click.self="planDraft = null"><form class="dialog" @submit.prevent="savePlan"><h2>点歌券套餐</h2><Field v-model="planDraft.name" label="名称" /><Field v-model="planDraft.description" label="说明" /><div class="grid grid-cols-2 gap-4"><Field v-model.number="planDraft.priceCents" type="number" label="价格（分）" /><Field v-model.number="planDraft.cardCount" type="number" label="点歌券数量" /></div><label class="check"><input v-model="planDraft.forSale" type="checkbox" />在售</label><div class="dialog-actions"><button type="button" class="small-button" @click="planDraft = null">取消</button><button class="primary-button">保存</button></div></form></div>
      <div v-if="refundDraft" class="modal" @click.self="refundDraft = null"><form class="dialog" @submit.prevent="refundOrder"><h2>订单退款</h2><Field v-model.number="refundDraft.amountCents" type="number" label="退款金额（分）" /><Field v-model="refundDraft.reason" label="原因" /><div class="dialog-actions"><button type="button" class="small-button" @click="refundDraft = null">取消</button><button class="primary-button">退款</button></div></form></div>
    </Teleport>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref, watch } from 'vue'
import { BarChart3, ClipboardList, CreditCard, Package, Pencil, Plus, RefreshCw, Save, Search, Trash2, Undo2 } from '@lucide/vue'
import AppSpinner from '~/components/UI/Common/AppSpinner.vue'; import CustomSelect from '~/components/UI/Common/CustomSelect.vue'; import { useLocale } from '~/utils/locale'; import { useServerErrors } from '~/composables/useLocaleText'
const Field = defineComponent({ props: { modelValue: [String, Number], label: String, placeholder: String, step: [String, Number], type: { type: String, default: 'text' } }, emits: ['update:modelValue'], setup(props, { emit }) { return () => h('label', { class: 'field' }, [h('span', props.label), h('input', { class: 'input w-full', value: props.modelValue ?? '', placeholder: props.placeholder, step: props.step, type: props.type, onInput: event => emit('update:modelValue', props.type === 'number' ? Number(event.target.value) : event.target.value) })]) } })
const sections = useLocale(); const locale = computed(() => sections.payment.value); const { localize } = useServerErrors(); const activeTab = ref('dashboard'); const loading = ref(true); const saving = ref(false); const errorMessage = ref('')
const settings = ref({ visibleMethods: [] }); const providers = ref([]); const plans = ref([]); const orders = ref([]); const dashboard = ref({}); const providerDraft = ref(null); const providerConfigJson = ref('{}'); const providerLimitsJson = ref('{}'); const planDraft = ref(null); const refundDraft = ref(null); const orderFilters = ref({ keyword: '', status: '' })
const tabIcons = { dashboard: BarChart3, orders: ClipboardList, plans: Package, settings: CreditCard }
const tabs = computed(() => ['dashboard', 'orders', 'plans', 'settings'].map(id => ({ id, label: locale.value.admin[id], icon: tabIcons[id] })))
const methods = ['alipay','wxpay','stripe','airwallex']; const methodLabel = value => ({ alipay: '支付宝', wxpay: '微信支付', stripe: 'Stripe', airwallex: 'Airwallex' }[value] || value)
const providerOptions = [{ value: 'easypay', label: 'EasyPay' }, { value: 'alipay', label: '支付宝官方' }, { value: 'wxpay', label: '微信支付官方' }, { value: 'stripe', label: 'Stripe' }, { value: 'airwallex', label: 'Airwallex' }]
const providerMethodsMap = { easypay: ['alipay','wxpay'], alipay: ['alipay'], wxpay: ['wxpay'], stripe: ['stripe'], airwallex: ['airwallex'] }
const providerMethods = computed(() => providerMethodsMap[providerDraft.value?.providerKey] || [])
const balanceOptions = [{ value: 'round-robin', label: '轮询' }, { value: 'least-amount', label: '最少金额' }]
const cancelModeOptions = [{ value: 'rolling', label: '滚动窗口' }, { value: 'fixed', label: '固定窗口' }]
const cancelUnitOptions = [{ value: 'minute', label: '分钟' }, { value: 'hour', label: '小时' }, { value: 'day', label: '天' }]
const statusOptions = [{ value: '', label: '全部状态' }, ...['PENDING','COMPLETED','FAILED','REFUND_REQUESTED','REFUNDING','REFUNDED','CANCELLED','EXPIRED'].map(value => ({ value, label: value }))]
const money = (cents, currency = 'CNY') => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cents / 100)
const api = async (url, options) => { try { return await $fetch(url, options) } catch (error) { errorMessage.value = localize(error); throw error } }
const loadOrders = async () => { const result = await api('/api/admin/payment/orders', { query: orderFilters.value }); orders.value = result.items }
const loadAll = async () => {
  loading.value = true
  errorMessage.value = ''
  try {
    const results = await Promise.allSettled([
      $fetch('/api/admin/payment/settings'),
      $fetch('/api/admin/payment/providers'),
      $fetch('/api/admin/payment/plans'),
      $fetch('/api/admin/payment/orders'),
      $fetch('/api/admin/payment/dashboard')
    ])
    const [settingsResult, providersResult, plansResult, ordersResult, dashboardResult] = results
    if (settingsResult.status === 'fulfilled') settings.value = settingsResult.value
    if (providersResult.status === 'fulfilled') providers.value = providersResult.value
    if (plansResult.status === 'fulfilled') plans.value = plansResult.value
    if (ordersResult.status === 'fulfilled') orders.value = ordersResult.value.items
    if (dashboardResult.status === 'fulfilled') dashboard.value = dashboardResult.value
    if (results.every(result => result.status === 'rejected')) errorMessage.value = localize(results[0].reason)
  } finally {
    loading.value = false
  }
}
const saveSettings = async () => { saving.value=true; try { settings.value = await api('/api/admin/payment/settings', { method:'PUT', body:settings.value }) } finally { saving.value=false } }
const editProvider = provider => { providerDraft.value = provider ? structuredClone(provider) : { providerKey:'easypay',name:'',supportedMethods:['alipay','wxpay'],enabled:true,sortOrder:0,refundEnabled:false,allowUserRefund:false }; providerConfigJson.value=JSON.stringify(provider?.config || {},null,2); providerLimitsJson.value=JSON.stringify(provider?.limits || {},null,2) }
watch(() => providerDraft.value?.providerKey, key => { if (providerDraft.value && !providerDraft.value.id) providerDraft.value.supportedMethods=[...(providerMethodsMap[key] || [])] })
const saveProvider = async () => { const body={...providerDraft.value,config:JSON.parse(providerConfigJson.value),limits:JSON.parse(providerLimitsJson.value)}; await api(providerDraft.value.id ? `/api/admin/payment/providers/${providerDraft.value.id}` : '/api/admin/payment/providers',{method:providerDraft.value.id?'PUT':'POST',body}); providerDraft.value=null; providers.value=await api('/api/admin/payment/providers') }
const removeProvider = async provider => { if (!confirm(`删除 ${provider.name}？`)) return; await api(`/api/admin/payment/providers/${provider.id}`,{method:'DELETE'}); providers.value=await api('/api/admin/payment/providers') }
const editPlan = plan => { planDraft.value=plan?structuredClone(plan):{name:'',description:'',priceCents:100,cardCount:1,currency:'CNY',features:[],forSale:true,sortOrder:0} }
const savePlan = async () => { await api(planDraft.value.id?`/api/admin/payment/plans/${planDraft.value.id}`:'/api/admin/payment/plans',{method:planDraft.value.id?'PUT':'POST',body:planDraft.value}); planDraft.value=null; plans.value=await api('/api/admin/payment/plans') }
const removePlan = async plan => { if (!confirm(`删除 ${plan.name}？`)) return; await api(`/api/admin/payment/plans/${plan.id}`,{method:'DELETE'}); plans.value=await api('/api/admin/payment/plans') }
const verifyOrder = async order => { await api(`/api/admin/payment/orders/${order.id}/verify`,{method:'POST'}); await loadOrders() }
const openRefund = order => { refundDraft.value={id:order.id,amountCents:order.payAmountCents-order.refundAmountCents,reason:'管理员退款'} }
const refundOrder = async () => { await api(`/api/admin/payment/orders/${refundDraft.value.id}/refund`,{method:'POST',body:refundDraft.value}); refundDraft.value=null; await loadOrders() }
onMounted(loadAll)
</script>

<style scoped>
.metric { display:flex; flex-direction:column; gap:.5rem; padding:1.25rem; border:1px solid var(--border-secondary); border-radius:.5rem; background:var(--bg-secondary); color:var(--text-tertiary) }.metric b{font-size:1.5rem;color:var(--text-primary)}
.payment-tabs{display:flex;gap:.25rem;align-items:center;overflow-x:auto;padding:.35rem;border:1px solid var(--border-secondary);border-radius:1rem;background:var(--bg-secondary);box-shadow:var(--shadow-md);scrollbar-width:none}.payment-tabs::-webkit-scrollbar{display:none}.payment-tab{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;min-width:7.4rem;min-height:2.65rem;padding:0 .9rem;border:1px solid transparent;border-radius:.8rem;background:transparent;color:var(--text-tertiary);font-size:.8rem;font-weight:700;white-space:nowrap;transition:color .15s,background .15s,border-color .15s,box-shadow .15s}.payment-tab:hover{color:var(--text-primary);background:var(--bg-hover)}.payment-tab.active{border-color:var(--primary);background:var(--bg-primary);color:var(--primary);box-shadow:var(--shadow-sm)}
.input { min-height:2.5rem; border:1px solid var(--border-secondary); border-radius:.5rem; background:var(--bg-secondary); padding:.6rem .75rem; color:var(--text-primary) }.primary-button,.small-button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;border-radius:.5rem;font-size:.8rem;font-weight:700}.primary-button{min-height:2.5rem;background:var(--primary);padding:0 1rem;color:white}.small-button{min-height:2.25rem;border:1px solid var(--border-secondary);padding:0 .75rem}.modal{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;background:#0009;padding:1rem}.dialog{width:100%;max-width:32rem;max-height:90vh;overflow:auto;border-radius:.5rem;background:var(--bg-primary);padding:1.5rem;color:var(--text-primary);display:flex;flex-direction:column;gap:1rem}.dialog h2{font-size:1.1rem;font-weight:800}.dialog label{font-size:.8rem;font-weight:700}.dialog-actions{display:flex;justify-content:flex-end;gap:.5rem}.check{display:flex;align-items:center;gap:.5rem}
